import numpy as np
PARK=np.array([0,0,0,1.5708,0,1.5708,0.0])
LO=np.array([-2.9,-2.0,-2.9,-2.4,-2.9,-2.0,-2.9]); HI=-LO
def Rz(a):
    c,s=np.cos(a),np.sin(a); M=np.eye(4); M[0,0]=c;M[0,1]=-s;M[1,0]=s;M[1,1]=c; return M
def Ry(a):
    c,s=np.cos(a),np.sin(a); M=np.eye(4); M[0,0]=c;M[0,2]=s;M[2,0]=-s;M[2,2]=c; return M
def T(x,y,z):
    M=np.eye(4); M[:3,3]=[x,y,z]; return M
def fk_all(q):
    q1,q2,q3,q4,q5,q6,q7=q
    A=Rz(q1)@T(0,0,.2); sh=A[:3,3].copy()
    A=A@Ry(q2)@Rz(q3)@T(0,0,.3); el=A[:3,3].copy()
    A=A@Ry(q4)@Rz(q5)@T(0,0,.3); wr=A[:3,3].copy()
    A=A@Ry(q6)@Rz(q7)@T(0,0,.1)
    return sh,el,wr,A
def fk(q): return fk_all(q)[3]
F=240/np.tan(np.radians(30))
def cam_pose(q):
    H=fk(q); R=H[:3,:3]; c=H[:3,3]+R[:,2]*0.011; return c,R
def project(q,P):
    c,R=cam_pose(q); p=R.T@(np.asarray(P)-c)
    if p[2]<=0: return None
    return np.array([240+F*p[0]/p[2], 240+F*p[1]/p[2]])
def ray(q,u,v):
    c,R=cam_pose(q); d=R@np.array([(u-240)/F,(v-240)/F,1.0]); return c,d/np.linalg.norm(d)
def pix_to_plane(q,u,v,z):
    c,d=ray(q,u,v); t=(z-c[2])/d[2]; return c+t*d
def rotvec_err(Ra,Rb):
    Rr=Ra.T@Rb; ang=np.arccos(np.clip((np.trace(Rr)-1)/2,-1,1))
    if ang<1e-9: return np.zeros(3)
    w=np.array([Rr[2,1]-Rr[1,2],Rr[0,2]-Rr[2,0],Rr[1,0]-Rr[0,1]])/(2*np.sin(ang)); return Ra@(w*ang)
def ik(pos,R=None,zdir=None,q0=None,iters=300,wrot=0.3,ref=None,wref=0.01):
    """pos: palm (hand origin) target; R full orientation or zdir only."""
    q=np.array(PARK if q0 is None else q0,float)
    for it in range(iters):
        H=fk(q); e=list(pos-H[:3,3])
        if R is not None: e+=list(wrot*rotvec_err(H[:3,:3],R)*1)
        elif zdir is not None: e+=list(wrot*np.cross(H[:3,2],zdir))
        e=np.array(e); J=np.zeros((len(e),7)); eps=1e-6
        for j in range(7):
            dq=np.zeros(7);dq[j]=eps;H2=fk(q+dq)
            f=list(H2[:3,3]-H[:3,3])
            if R is not None: f+=list(-wrot*rotvec_err(H2[:3,:3],H[:3,:3])) if False else list(wrot*(rotvec_err(H[:3,:3],R)-rotvec_err(H2[:3,:3],R))*-1)
            elif zdir is not None: f+=list(wrot*(np.cross(H2[:3,2],zdir)-np.cross(H[:3,2],zdir)))
            J[:,j]=np.array(f)/eps
        # e = target - current ; J = d(current-ish)/dq ; for orientation f = d(-err)... handle sign uniformly
        lam=1e-3
        r=PARK if ref is None else ref
        A=J.T@J+lam*np.eye(7)+wref*np.eye(7)
        b=J.T@e+wref*(r-q)
        dq=np.linalg.solve(A,b)
        q=np.clip(q+dq,LO,HI)
    return q
def check(q,pos=None,R=None,zdir=None):
    H=fk(q); out={'pos':H[:3,3].round(4)}
    if pos is not None: out['perr']=np.linalg.norm(H[:3,3]-pos)
    if zdir is not None: out['zerr']=np.degrees(np.arccos(np.clip(H[:3,2]@zdir,-1,1)))
    return out
