def _res(q,pos,R,zdir,xdir,wrot):
    H=fk(q); r=list(H[:3,3]-pos)
    if R is not None: r+=list(wrot*rotvec_err(R,H[:3,:3]))
    if zdir is not None: r+=list(wrot*(H[:3,2]-zdir))
    if xdir is not None: r+=list(wrot*(H[:3,0]-xdir))
    return np.array(r)
def ik2(pos,R=None,zdir=None,xdir=None,q0=None,iters=200,wrot=0.3,ref=None,wref=1e-3):
    q=np.array(PARK if q0 is None else q0,float); r0=PARK if ref is None else np.asarray(ref)
    for it in range(iters):
        r=_res(q,pos,R,zdir,xdir,wrot); J=np.zeros((len(r),7))
        for j in range(7):
            dq=np.zeros(7);dq[j]=1e-6; J[:,j]=(_res(q+dq,pos,R,zdir,xdir,wrot)-r)/1e-6
        A=J.T@J+(1e-4+wref)*np.eye(7); b=-J.T@r+wref*(r0-q)
        q=np.clip(q+np.linalg.solve(A,b),LO,HI)
    return q
