import numpy as np, sys
from PIL import Image
def load(f): return np.asarray(Image.open(f).convert('RGB')).astype(float)
def classify(a):
    r,g,b=a[...,0],a[...,1],a[...,2]
    lab=np.full(a.shape[:2],'?',dtype='<U1')
    gray=(abs(r-g)<20)&(abs(g-b)<20)
    lab[gray&(r>150)]='G'; lab[gray&(r<=150)&(r>60)]='g'; lab[gray&(r<=60)]='k'
    blue=(b-r>40)
    lab[blue&(r>110)]='L'; lab[blue&(r<=110)&(r>60)]='M'; lab[blue&(r<=60)&(g>45)]='D'
    lab[(b-r>30)&(r<40)&(g<40)]='N'
    return lab
def runs(row):
    out=[];s=0
    for i in range(1,len(row)+1):
        if i==len(row) or row[i]!=row[s]:
            out.append(f'{row[s]}{s}-{i-1}');s=i
    return ' '.join(out)
if __name__=='__main__':
    a=load(sys.argv[1]); lab=classify(a)
    rows=[int(x) for x in sys.argv[2].split(',')]
    for r in rows: print(r,runs(lab[r]))
