    # hand z: down and toward -y by beta; hand x across track (cell -x if flip=1)
    z=np.array([0,-np.sin(beta),-np.cos(beta)]); x=np.array([-1.0*flip,0,0]); y=np.cross(z,x)
    return np.column_stack([x,y,z])
