def ik_multi(pos,R,start=PARK,n=30,seed=0,tol=2e-4):
    rng=np.random.default_rng(seed); sols=[]
    starts=[np.array(start,float)]+[np.array(start)+rng.normal(0,0.5,7) for _ in range(n)]
    for s in starts:
        s=np.clip(s,LO,HI)
        for wref in [1e-3,1e-5]:
            q=ik3(pos,R,q0=s,ref=start,wref=wref,iters=200)
            e=np.linalg.norm(_res(q,pos,R,None,None,1.0))
            if e<tol: sols.append((np.abs(q-start).max(),q,e))
    sols.sort(key=lambda t:t[0])
    return sols
