import numpy as np
from PIL import Image, ImageDraw
from frame import *
def paint(base,q,yf,L=0.04,Wd=0.03,Hh=0.03,out='syn.png',color=(200,60,40)):
    im=Image.open(base).convert('RGB'); dr=ImageDraw.Draw(im)
    c,R=cam(q); pts=[]
    for dy in [0,-L]:
        for dx in [-Wd/2,Wd/2]:
            for dz in [0,Hh]:
                y=yf+dy; P=np.array([XT+dx,y,zfloor(y)+dz]); p=R.T@(P-c)
                pts.append((240+415.7*(p[0]/p[2]+TH),240+415.7*p[1]/p[2]))
    pts=np.array(pts)
    # convex hull
    from math import atan2
    cen=pts.mean(0); ang=np.arctan2(pts[:,1]-cen[1],pts[:,0]-cen[0]); 
    # gift wrap
    def hull(P):
        P=sorted(map(tuple,P)); 
        def cross(o,a,b): return (a[0]-o[0])*(b[1]-o[1])-(a[1]-o[1])*(b[0]-o[0])
        lo=[];up=[]
        for p in P:
            while len(lo)>=2 and cross(lo[-2],lo[-1],p)<=0: lo.pop()
            lo.append(p)
        for p in reversed(P):
            while len(up)>=2 and cross(up[-2],up[-1],p)<=0: up.pop()
            up.append(p)
        return lo[:-1]+up[:-1]
    dr.polygon(hull(pts),fill=color); im.save(out)
if __name__=='__main__':
    q=np.array([0.812,0.624,-0.282,1.128,-0.542,1.526,0.299])
