import numpy as np, json, sys
YC=0.17
def load_obs(extra=None):
    obs=[]
    for line in open('try/log.jsonl'):
        e=json.loads(line); d=e['det']
        if d and e.get('use',True): obs.append((e['state']['time'],d['front_bottom'][1]))
    return obs
def fits(obs,L):
    t=np.array([o[0] for o in obs]); y=np.array([o[1] for o in obs])
    out={}
    target=YC+L/2; entry=YC-0.02
    def solve(coef,yt):
        # coef: y = c0 + c1 t + c2 t^2
        c0,c1,c2=coef
        ts=np.linspace(t.max(),4.5,4501); yy=c0+c1*ts+c2*ts*ts
        idx=np.where(yy>=yt)[0]; return float(ts[idx[0]]) if len(idx) else None
    if len(t)>=3:
        c=np.polyfit(t,y,2)[::-1]; out['quad']=(c.round(4).tolist(),solve(c,target),solve(c,entry))
    if len(t)>=2:
        c=np.polyfit(t,y,1)[::-1]; c=[c[0],c[1],0]; out['lin']=(np.round(c,4).tolist(),solve(c,target),solve(c,entry))
        # from-rest model: y = y0 + 0.5 a (t-t0)^2 with t0=0: fit y0,a
        A=np.c_[np.ones(len(t)),0.5*t*t]; s=np.linalg.lstsq(A,y,rcond=None)[0]; c=[s[0],0,0.5*s[1]]
        out['rest']=(np.round(c,4).tolist(),solve(c,target),solve(c,entry))
        # last two points, constant accel = from rest-fit accel
    return out
if __name__=='__main__':
    L=float(sys.argv[1]) if len(sys.argv)>1 else 0.04
    obs=load_obs(); print(obs)
    for k,v in fits(obs,L).items(): print(k,v)
